objects.sourceDdl:
CREATE TABLE 'etf_adj' ( 
	ts_code SYMBOL,
	adj_factor DOUBLE,
	timestamp TIMESTAMP
) timestamp(timestamp) PARTITION BY YEAR
DEDUP UPSERT KEYS(ts_code,timestamp);

CREATE TABLE 'stk_st_daily' ( 
	ts_code SYMBOL NOCACHE,
	is_st INT,
	timestamp TIMESTAMP
) timestamp(timestamp) PARTITION BY YEAR
DEDUP UPSERT KEYS(ts_code,timestamp);

CREATE TABLE 'stk_suspend' ( 
	ts_code SYMBOL NOCACHE,
	is_suspended LONG,
	timestamp TIMESTAMP
) timestamp(timestamp) PARTITION BY DAY
DEDUP UPSERT KEYS(ts_code,timestamp);
